import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.qUUbSc2K.js";var i=JSON.parse(`{"title":"Unplugin","description":"Configure PikaCSS with supported Rollup-family and Webpack-family bundlers.","frontmatter":{"title":"Unplugin","description":"Configure PikaCSS with supported Rollup-family and Webpack-family bundlers.","relatedPackages":["@pikacss/unplugin-pikacss"],"relatedSources":["packages/unplugin/src/index.ts","packages/unplugin/src/types.ts","packages/unplugin/src/cli.ts"],"category":"integrations","order":10},"headers":[],"relativePath":"integrations/unplugin.md","filePath":"integrations/unplugin.md"}`),a={name:`integrations/unplugin.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /integrations/unplugin.md for this page in Markdown format</div><h1 id="unplugin" tabindex="-1">Unplugin <a class="header-anchor" href="#unplugin" aria-label="Permalink to “Unplugin”">​</a></h1><p>PikaCSS uses <a href="https://github.com/unjs/unplugin" target="_blank" rel="noreferrer">unplugin</a> as an adapter layer, but support is intentionally limited to the Rollup and Webpack families.</p><p>The Vite entry supports Vite 7 and 8 only.</p><h2 id="supported-tools" tabindex="-1">Supported Tools <a class="header-anchor" href="#supported-tools" aria-label="Permalink to “Supported Tools”">​</a></h2><table tabindex="0"><thead><tr><th>Family</th><th>Bundler</th><th>Import Path</th></tr></thead><tbody><tr><td>Rollup</td><td>Vite</td><td><code>@pikacss/unplugin-pikacss/vite</code></td></tr><tr><td>Rollup</td><td>Rollup</td><td><code>@pikacss/unplugin-pikacss/rollup</code></td></tr><tr><td>Rollup</td><td>Rolldown</td><td><code>@pikacss/unplugin-pikacss/rolldown</code></td></tr><tr><td>Webpack</td><td>Webpack</td><td><code>@pikacss/unplugin-pikacss/webpack</code></td></tr><tr><td>Webpack</td><td>Rspack</td><td><code>@pikacss/unplugin-pikacss/rspack</code></td></tr></tbody></table><p>Other Unplugin hosts, including esbuild, are outside the supported surface and have no public PikaCSS adapter entry point. Import an explicit supported bundler subpath rather than the package root when configuring a bundler plugin.</p><p>Example with Vite:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// vite.config.ts</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PikaCSS </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@pikacss/unplugin-pikacss/vite&#39;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { defineConfig } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vite&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> defineConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  plugins: [</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    PikaCSS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">      // options</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Vite plugin order</p><p>The Vite entry registers with <code>enforce: &#39;pre&#39;</code>. PikaCSS still runs before framework compiler plugins even if your Vite <code>plugins</code> array is ordered as <code>[vue(), pikacss()]</code>, so you do not need to reorder the array just to avoid template compile errors.</p></div><h2 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to “Config”">​</a></h2><p>The bundler adapter has only two bootstrap selectors. Source scanning, function roots, CSS-module names, transform format, generated-state placement, Engine behavior, and production reports belong to the canonical PikaCSS project config.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>cwd</code></td><td><code>string?</code></td><td>Optional project-root override. Normally the supported bundler supplies its resolved root/context.</td></tr><tr><td><code>config</code></td><td><code>string?</code></td><td>Optional explicit PikaCSS config file. Relative paths are resolved from the selected project root; when omitted, canonical project-root discovery is used.</td></tr></tbody></table><blockquote><p>See <a href="/api/unplugin.html">API Reference — Unplugin</a> for exact type signatures.</p></blockquote><h2 id="diagnostics-and-reporting" tabindex="-1">Diagnostics and Reporting <a class="header-anchor" href="#diagnostics-and-reporting" aria-label="Permalink to “Diagnostics and Reporting”">​</a></h2><p>Engine plugins can report diagnostics during transforms (for example, <a href="/official-plugins/design-tokens.html#strict-mode"><code>@pikacss/plugin-design-tokens</code></a> strict mode). The engine never throws them — it hands each <code>Diagnostic</code> (<code>{ level, code, message, plugin?, … }</code>) to a handler. The unplugin installs that handler for you; there is no <code>onDiagnostic</code> plugin option to set.</p><h3 id="how-diagnostics-surface" tabindex="-1">How diagnostics surface <a class="header-anchor" href="#how-diagnostics-surface" aria-label="Permalink to “How diagnostics surface”">​</a></h3><p>The built-in handler logs <strong>every</strong> diagnostic live, so a <code>&#39;warning&#39;</code> appears immediately during dev and build. It also collects the <code>&#39;error&#39;</code>-level diagnostics and, once every module has been transformed, throws a single aggregated <code>Error</code> at <code>buildEnd</code> listing them all — so an error-severity diagnostic <strong>fails a production build</strong>.</p><div class="info custom-block"><p class="custom-block-title">Why the build fails at <code>buildEnd</code>, not inline</p><p>Core delivers diagnostics through a handler whose throws are swallowed, so a handler cannot abort a single module&#39;s transform. Errors are therefore aggregated and thrown once at <code>buildEnd</code>. The trade-off: an error surfaces after the full build rather than inline on the producing module (with Vite&#39;s dev overlay). Warnings still log live on the module that produced them.</p></div><h3 id="production-reports" tabindex="-1">Production reports <a class="header-anchor" href="#production-reports" aria-label="Permalink to “Production reports”">​</a></h3><p>Production reporting is configured per entry in the canonical PikaCSS project config, not as a bundler-plugin option. <code>report: true</code> enables the final summary for that entry; <code>{ output }</code> additionally publishes its JSON report to the config-relative path.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// pika.config.ts</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { defineConfig } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@pikacss/unplugin-pikacss&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> defineConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  report: { output: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;./design-tokens.report.json&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>The adapter only owns host lifecycle presentation. Reports finalize after a successful one-shot production build on supported Rollup-family and Webpack-family hosts; dev/watch lifecycles do not publish final reports. Report producer, serialization, directory, write, or atomic-replacement failures reject the production build.</p><h2 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to “CLI”">​</a></h2><p>A direct install of <code>@pikacss/unplugin-pikacss</code> provides the <code>pikacss</code> binary. The CLI is intentionally narrow:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pikacss</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--cwd </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">di</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pikacss</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepare</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--cwd </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">di</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--config </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span></code></pre></div><p><code>init</code> creates only a canonical PikaCSS config when none exists and prints setup guidance; it does not modify package metadata, TypeScript config, or ignore files. <code>prepare</code> performs deterministic generated-state publication only. It does not source-scan, build runtime CSS, start watchers, or emit final production reports.</p><p><code>--cwd</code> selects the host project root. <code>--config</code> is available to <code>prepare</code> as the same explicit closed config-file selector used by the bundler adapter.</p><h2 id="typescript-and-logical-css-modules" tabindex="-1">TypeScript and logical CSS modules <a class="header-anchor" href="#typescript-and-logical-css-modules" aria-label="Permalink to “TypeScript and logical CSS modules”">​</a></h2><p>In Vite projects, the ambient <code>*.css</code> module declaration from <code>vite/client</code> covers logical CSS-module specifiers such as the single-entry default <code>pika.css</code>. PikaCSS itself ships no ambient declaration for those specifiers, so TypeScript projects on other bundlers (Webpack, Rspack, Rollup, Rolldown) may report <code>TS2307</code> for the configured <code>cssModule</code>. Add a shim for each logical module your application imports:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// pika-css.d.ts</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">declare</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;pika.css&#39;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"> // or your configured logical cssModule</span></span></code></pre></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/integrations/nuxt.html">Nuxt</a> — zero-config Nuxt integration.</li><li><a href="/getting-started/setup.html">Setup</a> — basic project setup.</li></ul>`,33)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};